 .../plasmacomponents3/MenuItem.qml            |   3 +
 .../plasmacomponents3/TextField.qml           |   2 +
 .../private/TextFieldContextMenu.qml          | 120 ++++++++++++++++++
 4 files changed, 125 insertions(+), 1 deletion(-)
 create mode 100644 src/declarativeimports/plasmacomponents3/private/TextFieldContextMenu.qml

